import {EMPTY,legalMoves,landingRow,winningLines} from './engine.js';
const WINDOWS=[];for(let r=0;r<6;r++)for(let c=0;c<7;c++)for(const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]){const rr=r+dr*3,cc=c+dc*3;if(rr>=0&&rr<6&&cc>=0&&cc<7)WINDOWS.push([0,1,2,3].map(i=>(r+dr*i)*7+c+dc*i));}
function wonAt(b,r,c,p){for(const [dr,dc]of [[0,1],[1,0],[1,1],[1,-1]]){let n=1;for(const dir of [-1,1]){let rr=r+dr*dir,cc=c+dc*dir;while(rr>=0&&rr<6&&cc>=0&&cc<7&&b[rr*7+cc]===p){n++;rr+=dr*dir;cc+=dc*dir;}}if(n>=4)return true;}return false;}
export function immediateWins(b,p){return legalMoves(b).filter(c=>{const r=landingRow(b,c);b[r*7+c]=p;const w=wonAt(b,r,c,p);b[r*7+c]=EMPTY;return w;});}
function evaluate(b,p){let score=0;for(let r=0;r<6;r++){if(b[r*7+3]===p)score+=8;else if(b[r*7+3]===1-p)score-=8;}for(const w of WINDOWS){let mine=0,theirs=0,empty=-1;for(const i of w){if(b[i]===p)mine++;else if(b[i]===1-p)theirs++;else empty=i;}if(!theirs){score+=[0,1,10,70,100000][mine];if(mine===3&&(empty>=35||b[empty+7]!==EMPTY))score+=110;}if(!mine){score-=[0,1,12,85,100000][theirs];if(theirs===3&&(empty>=35||b[empty+7]!==EMPTY))score-=130;}}return score;}
export function chooseMove(board,player,difficulty='hard',options={}){const b=[...board],valid=legalMoves(b);if(!valid.length||winningLines(b).length)return null;const random=options.random??Math.random,wins=immediateWins(b,player),blocks=immediateWins(b,1-player);if(difficulty==='easy'){if(wins.length&&random()<.65)return wins[0];if(blocks.length&&random()<.35)return blocks[0];return valid[Math.floor(random()*valid.length)];}if(wins.length)return wins[0];if(blocks.length===1)return blocks[0];const deadline=performance.now()+(options.budget??(difficulty==='hard'?620:100)),maxDepth=options.depth??(difficulty==='hard'?9:4);let nodes=0,tt=new Map(),best=valid[0],timeout=false;
function search(depth,alpha,beta,turn,ply){if((++nodes&255)===0&&performance.now()>deadline){timeout=true;return 0;}const moves=legalMoves(b);if(!moves.length)return 0;if(depth===0)return evaluate(b,player);const key=b.map(v=>v+1).join('')+turn,old=tt.get(key);const initialAlpha=alpha,initialBeta=beta;if(old&&old.depth>=depth){if(old.flag==='exact')return old.value;if(old.flag==='lower')alpha=Math.max(alpha,old.value);else beta=Math.min(beta,old.value);if(alpha>=beta)return old.value;}if(old&&moves.includes(old.col)){moves.splice(moves.indexOf(old.col),1);moves.unshift(old.col);}let value=turn===player?-Infinity:Infinity,col=moves[0];for(const c of moves){const r=landingRow(b,c);b[r*7+c]=turn;const v=wonAt(b,r,c,turn)?(turn===player?100000-ply:-100000+ply):search(depth-1,alpha,beta,1-turn,ply+1);b[r*7+c]=EMPTY;if(timeout)return 0;if((turn===player&&v>value)||(turn!==player&&v<value)){value=v;col=c;}if(turn===player)alpha=Math.max(alpha,value);else beta=Math.min(beta,value);if(beta<=alpha)break;}if(tt.size<90000)tt.set(key,{depth,value,col,flag:value<=initialAlpha?'upper':value>=initialBeta?'lower':'exact'});return value;}
let ranked=[];for(let depth=1;depth<=maxDepth;depth++){let roundBest=-Infinity,roundCol=best;const ordered=[best,...valid.filter(c=>c!==best)],values=[];for(const c of ordered){const r=landingRow(b,c);b[r*7+c]=player;const v=search(depth-1,-Infinity,Infinity,1-player,1);b[r*7+c]=EMPTY;if(timeout)break;values.push({c,v});if(v>roundBest){roundBest=v;roundCol=c;}}if(timeout)break;best=roundCol;ranked=values.sort((a,b)=>b.v-a.v);if(roundBest>90000||performance.now()>deadline)break;}if(difficulty==='medium'&&ranked.length>1&&random()<.14){const near=ranked.filter(x=>x.v>ranked[0].v-85&&x.v>-90000);if(near.length>1)return near[1].c;}return best;}
